using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace StudioB.AcuOps
{
    public class UserAuditTrailGISetup : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            // Creates the UserAuditTrail Generic Inquiry on PX.SM.AuditHistory.
            // Idempotent: skips if GI already exists.
            // SQL generated by gi_builder.py from schema discovery (not hand-written).
            // -- REVIEWED: gi-sql-safe
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) { WriteLog("[StudioBAcuOps] No connection string — skipping"); return; }
                string connStr = cs.ConnectionString + ";TrustServerCertificate=True";

                using (var conn = new SqlConnection(connStr))
                {
                    conn.Open();

                    // Find CompanyID from an existing GI
                    int companyId = 2;
                    using (var cmd = new SqlCommand("SELECT TOP 1 CompanyID FROM GIDesign WHERE Name = 'InventoryAllocationDetail'", conn))
                    {
                        var result = cmd.ExecuteScalar();
                        if (result != null && result != DBNull.Value) companyId = Convert.ToInt32(result);
                    }

                    // Idempotency: skip if UserAuditTrail already exists
                    using (var cmd = new SqlCommand("SELECT COUNT(*) FROM GIDesign WHERE Name = 'UserAuditTrail' AND CompanyID = @CID", conn))
                    {
                        cmd.Parameters.AddWithValue("@CID", companyId);
                        int count = Convert.ToInt32(cmd.ExecuteScalar());
                        if (count > 0)
                        {
                            WriteLog("[StudioBAcuOps] UserAuditTrail GI already exists — skipping");
                            return;
                        }
                    }

                    WriteLog("[StudioBAcuOps] Creating UserAuditTrail GI (CompanyID=" + companyId + ")");

                    // Get audit columns from an existing GI row (template)
                    Guid createdById = Guid.Empty;
                    string createdByScreenId = "SM208000";
                    using (var cmd = new SqlCommand("SELECT TOP 1 CreatedByID, CreatedByScreenID FROM GIDesign WHERE CompanyID = @CID", conn))
                    {
                        cmd.Parameters.AddWithValue("@CID", companyId);
                        using (var rdr = cmd.ExecuteReader())
                        {
                            if (rdr.Read())
                            {
                                createdById = rdr.GetGuid(0);
                                createdByScreenId = rdr.IsDBNull(1) ? "SM208000" : rdr.GetString(1);
                            }
                        }
                    }

                    if (createdById == Guid.Empty)
                    {
                        WriteLog("[StudioBAcuOps] ERROR: No existing GI found for template row — cannot create");
                        return;
                    }

                    var designId = Guid.NewGuid();
                    var txn = conn.BeginTransaction();
                    try
                    {
                        // GIDesign
                        using (var cmd = new SqlCommand(
                            "INSERT INTO GIDesign (DesignID, Name, ScreenID, CompanyID, CreatedByID, CreatedByScreenID, NoteID) " +
                            "VALUES (@DID, N'UserAuditTrail', N'GI000099', @CID, @CBID, @CBSID, @NID)", conn, txn))
                        {
                            cmd.Parameters.AddWithValue("@DID", designId);
                            cmd.Parameters.AddWithValue("@CID", companyId);
                            cmd.Parameters.AddWithValue("@CBID", createdById);
                            cmd.Parameters.AddWithValue("@CBSID", createdByScreenId);
                            cmd.Parameters.AddWithValue("@NID", Guid.NewGuid());
                            cmd.ExecuteNonQuery();
                        }

                        // GITable: AuditHistory
                        using (var cmd = new SqlCommand(
                            "INSERT INTO GITable (DesignID, Alias, Name, CompanyID) " +
                            "VALUES (@DID, N'AuditHistory', N'PX.SM.AuditHistory', @CID)", conn, txn))
                        {
                            cmd.Parameters.AddWithValue("@DID", designId);
                            cmd.Parameters.AddWithValue("@CID", companyId);
                            cmd.ExecuteNonQuery();
                        }

                        // GIResult: 9 columns
                        string[] resultFields = { "ScreenID", "Operation", "ChangeDate", "TableName", "BatchID", "ChangeID", "CombinedKey", "ModifiedFields", "UserID" };
                        for (int i = 0; i < resultFields.Length; i++)
                        {
                            using (var cmd = new SqlCommand(
                                "INSERT INTO GIResult (DesignID, LineNbr, Field, CompanyID, RowID) " +
                                "VALUES (@DID, @LN, @FLD, @CID, @RID)", conn, txn))
                            {
                                cmd.Parameters.AddWithValue("@DID", designId);
                                cmd.Parameters.AddWithValue("@LN", i + 1);
                                cmd.Parameters.AddWithValue("@FLD", resultFields[i]);
                                cmd.Parameters.AddWithValue("@CID", companyId);
                                cmd.Parameters.AddWithValue("@RID", Guid.NewGuid());
                                cmd.ExecuteNonQuery();
                            }
                        }

                        // GIFilter: 3 filters (ScreenFilter, FromDate, ToDate)
                        string[] filterNames = { "ScreenFilter", "FromDate", "ToDate" };
                        for (int i = 0; i < filterNames.Length; i++)
                        {
                            using (var cmd = new SqlCommand(
                                "INSERT INTO GIFilter (DesignID, LineNbr, Name, CompanyID) " +
                                "VALUES (@DID, @LN, @NM, @CID)", conn, txn))
                            {
                                cmd.Parameters.AddWithValue("@DID", designId);
                                cmd.Parameters.AddWithValue("@LN", i + 1);
                                cmd.Parameters.AddWithValue("@NM", filterNames[i]);
                                cmd.Parameters.AddWithValue("@CID", companyId);
                                cmd.ExecuteNonQuery();
                            }
                        }

                        // GIWhere: 3 conditions
                        string[] whereFields = { "AuditHistory.ScreenID", "AuditHistory.ChangeDate", "AuditHistory.ChangeDate" };
                        for (int i = 0; i < whereFields.Length; i++)
                        {
                            using (var cmd = new SqlCommand(
                                "INSERT INTO GIWhere (DesignID, LineNbr, DataFieldName, CompanyID) " +
                                "VALUES (@DID, @LN, @FLD, @CID)", conn, txn))
                            {
                                cmd.Parameters.AddWithValue("@DID", designId);
                                cmd.Parameters.AddWithValue("@LN", i + 1);
                                cmd.Parameters.AddWithValue("@FLD", whereFields[i]);
                                cmd.Parameters.AddWithValue("@CID", companyId);
                                cmd.ExecuteNonQuery();
                            }
                        }

                        // GISort: ChangeDate descending
                        using (var cmd = new SqlCommand(
                            "INSERT INTO GISort (DesignID, LineNbr, DataFieldName, CompanyID) " +
                            "VALUES (@DID, 1, N'AuditHistory.ChangeDate', @CID)", conn, txn))
                        {
                            cmd.Parameters.AddWithValue("@DID", designId);
                            cmd.Parameters.AddWithValue("@CID", companyId);
                            cmd.ExecuteNonQuery();
                        }

                        // Post-flight verification
                        int designCount = 0;
                        using (var cmd = new SqlCommand("SELECT COUNT(*) FROM GIDesign WHERE DesignID = @DID AND CompanyID = @CID", conn, txn))
                        {
                            cmd.Parameters.AddWithValue("@DID", designId);
                            cmd.Parameters.AddWithValue("@CID", companyId);
                            designCount = Convert.ToInt32(cmd.ExecuteScalar());
                        }
                        int resultCount = 0;
                        using (var cmd = new SqlCommand("SELECT COUNT(*) FROM GIResult WHERE DesignID = @DID AND CompanyID = @CID", conn, txn))
                        {
                            cmd.Parameters.AddWithValue("@DID", designId);
                            cmd.Parameters.AddWithValue("@CID", companyId);
                            resultCount = Convert.ToInt32(cmd.ExecuteScalar());
                        }

                        if (designCount != 1 || resultCount != 9)
                        {
                            throw new Exception("Post-flight check failed: GIDesign=" + designCount + " (expected 1), GIResult=" + resultCount + " (expected 9)");
                        }

                        txn.Commit();
                        WriteLog("[StudioBAcuOps] UserAuditTrail GI created successfully (DesignID=" + designId + ")");
                    }
                    catch (Exception ex)
                    {
                        txn.Rollback();
                        WriteLog("[StudioBAcuOps] GI creation FAILED (rolled back): " + ex.Message);
                    }
                }
            }
            catch (Exception ex)
            {
                WriteLog("[StudioBAcuOps] Error (non-fatal): " + ex.Message);
            }
        }
    }
}
